package com.example.jobfinderapp.models;
public class Education { private int id,userId; private String schoolName,major,degree,startDate,endDate,gpa,description; public Education(){} public int getId(){return id;}public void setId(int v){id=v;}public int getUserId(){return userId;}public void setUserId(int v){userId=v;}public String getSchoolName(){return schoolName;}public void setSchoolName(String v){schoolName=v;}public String getMajor(){return major;}public void setMajor(String v){major=v;}public String getDegree(){return degree;}public void setDegree(String v){degree=v;}public String getStartDate(){return startDate;}public void setStartDate(String v){startDate=v;}public String getEndDate(){return endDate;}public void setEndDate(String v){endDate=v;}public String getGpa(){return gpa;}public void setGpa(String v){gpa=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;} }
